-- =============================================================================
-- SAP Security Expert — Complete Production Database Schema
-- =============================================================================
-- Source  : Production export sapsecurity_expert (5).sql (MariaDB 10.11.18,
--           exported 2026-06-22 via phpMyAdmin 5.2.2) + all codebase migrations
-- Target  : MariaDB 10.11, AWS Lightsail (Debian 12)
-- Usage   : mysql -u <user> -p <database> < schema.sql
-- Note    : All CREATE TABLE use IF NOT EXISTS — safe to re-run on existing DB.
--           The `sessions` table is auto-created by express-mysql-session on
--           first server startup and is NOT included here.
-- =============================================================================

SET SQL_MODE = "NO_AUTO_VALUE_ON_ZERO";
START TRANSACTION;
SET time_zone = "+00:00";
/*!40101 SET NAMES utf8mb4 */;

-- =============================================================================
-- TABLE DEFINITIONS
-- =============================================================================

-- --------------------------------------------------------
-- ads
-- --------------------------------------------------------
CREATE TABLE IF NOT EXISTS `ads` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `zone` varchar(100) NOT NULL,
  `image` longtext DEFAULT NULL,
  `link` longtext DEFAULT NULL,
  `active` tinyint(1) DEFAULT 0,
  `created_at` datetime DEFAULT current_timestamp(),
  `status` varchar(50) DEFAULT 'inactive',
  `title` varchar(255) DEFAULT NULL,
  `ad_size` varchar(50) DEFAULT NULL,
  `start_date` date DEFAULT NULL,
  `end_date` date DEFAULT NULL,
  `clicks` int(11) DEFAULT 0,
  PRIMARY KEY (`id`),
  UNIQUE KEY `zone` (`zone`) USING HASH
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- --------------------------------------------------------
-- analytics
-- --------------------------------------------------------
CREATE TABLE IF NOT EXISTS `analytics` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `post_id` varchar(255) DEFAULT NULL,
  `ip_hash` varchar(255) DEFAULT NULL,
  `event_type` varchar(100) DEFAULT NULL,
  `path` longtext DEFAULT NULL,
  `created_at` datetime DEFAULT current_timestamp(),
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- --------------------------------------------------------
-- announcements
-- Includes columns added post-launch via db.js migrations:
--   slug, content, excerpt, image, image_alt, updated_at
-- --------------------------------------------------------
CREATE TABLE IF NOT EXISTS `announcements` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `title` longtext NOT NULL,
  `date` datetime NOT NULL,
  `views` int(11) DEFAULT 0,
  `comments` int(11) DEFAULT 0,
  `link` longtext DEFAULT NULL,
  `status` varchar(50) DEFAULT 'active',
  `created_at` datetime DEFAULT current_timestamp(),
  `publish_date` datetime DEFAULT NULL,
  `draft_title` longtext DEFAULT NULL,
  `draft_date` date DEFAULT NULL,
  `draft_link` longtext DEFAULT NULL,
  `submission_status` varchar(255) DEFAULT 'approved',
  `seo_score` int(11) DEFAULT 0,
  `plagiarism_score` int(11) DEFAULT 0,
  `rejection_feedback` longtext DEFAULT NULL,
  `slug` varchar(500) DEFAULT '',
  `content` longtext DEFAULT NULL,
  `excerpt` longtext DEFAULT NULL,
  `image` longtext DEFAULT NULL,
  `image_alt` varchar(255) DEFAULT '',
  `updated_at` datetime DEFAULT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=18 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- --------------------------------------------------------
-- audit_logs
-- --------------------------------------------------------
CREATE TABLE IF NOT EXISTS `audit_logs` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `user_id` int(11) DEFAULT NULL,
  `action` varchar(255) DEFAULT NULL,
  `target_type` varchar(100) DEFAULT NULL,
  `target_id` varchar(255) DEFAULT NULL,
  `details` longtext DEFAULT NULL,
  `timestamp` datetime DEFAULT current_timestamp(),
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=433 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- --------------------------------------------------------
-- blogs
-- Includes ALL columns from original schema + migrations:
--   add_secondary_categories.sql  → secondary_categories, draft_secondary_categories
--   add_image_alt.sql             → image_alt, draft_image_alt
--   add_news_type.sql             → type
--   add_premium_membership.sql    → is_premium
--   add_schema_fields.sql         → schema_type, article_section
--   db.js                         → co_authors, send_notification_email, credits_required
-- --------------------------------------------------------
CREATE TABLE IF NOT EXISTS `blogs` (
  `id` varchar(255) NOT NULL,
  `title` longtext NOT NULL,
  `slug` varchar(255) NOT NULL,
  `excerpt` longtext DEFAULT NULL,
  `content` longtext DEFAULT NULL,
  `author` varchar(255) DEFAULT 'Admin',
  `date` datetime DEFAULT NULL,
  `image` longtext DEFAULT NULL,
  `category` varchar(255) DEFAULT 'sap-security',
  `subCategory` longtext DEFAULT NULL,
  `tags` longtext DEFAULT NULL,
  `view_count` int(11) DEFAULT 0,
  `meta_title` longtext DEFAULT NULL,
  `meta_description` longtext DEFAULT NULL,
  `status` varchar(50) DEFAULT 'published',
  `created_at` datetime DEFAULT current_timestamp(),
  `faq` longtext DEFAULT NULL,
  `cta_title` varchar(255) DEFAULT NULL,
  `cta_description` longtext DEFAULT NULL,
  `cta_button_text` varchar(100) DEFAULT NULL,
  `cta_button_link` varchar(255) DEFAULT NULL,
  `author_id` int(11) DEFAULT NULL,
  `faqs` longtext DEFAULT NULL,
  `meta_keywords` longtext DEFAULT NULL,
  `submission_status` varchar(255) NOT NULL DEFAULT 'approved',
  `draft_title` longtext DEFAULT NULL,
  `draft_excerpt` longtext DEFAULT NULL,
  `draft_content` longtext DEFAULT NULL,
  `draft_meta_title` longtext DEFAULT NULL,
  `draft_meta_description` longtext DEFAULT NULL,
  `draft_meta_keywords` longtext DEFAULT NULL,
  `draft_cta_title` longtext DEFAULT NULL,
  `draft_cta_description` longtext DEFAULT NULL,
  `draft_cta_button_text` longtext DEFAULT NULL,
  `draft_cta_button_link` longtext DEFAULT NULL,
  `draft_image` longtext DEFAULT NULL,
  `draft_category` longtext DEFAULT NULL,
  `draft_subCategory` longtext DEFAULT NULL,
  `draft_tags` longtext DEFAULT NULL,
  `draft_faqs` longtext DEFAULT NULL,
  `draft_related_blogs` longtext DEFAULT NULL,
  `draft_is_members_only` int(11) NOT NULL DEFAULT 0,
  `seo_score` int(11) DEFAULT 0,
  `plagiarism_score` int(11) DEFAULT 0,
  `rejection_feedback` longtext DEFAULT NULL,
  `publish_date` datetime DEFAULT NULL,
  `plagiarism_status` varchar(255) DEFAULT 'pending',
  `plagiarism_checked_at` datetime DEFAULT NULL,
  `publish_datetime` datetime DEFAULT NULL,
  `updated_at` datetime DEFAULT NULL,
  `reviewed_at` datetime DEFAULT NULL,
  `reviewed_by` int(11) DEFAULT NULL,
  `is_members_only` int(11) NOT NULL DEFAULT 0,
  `related_blogs` longtext DEFAULT NULL,
  `is_queued_for_members` tinyint(4) DEFAULT 0,
  `secondary_categories` longtext DEFAULT NULL,
  `draft_secondary_categories` longtext DEFAULT NULL,
  `image_alt` varchar(500) DEFAULT '',
  `draft_image_alt` varchar(500) DEFAULT '',
  `co_authors` longtext DEFAULT NULL,
  `type` varchar(20) NOT NULL DEFAULT 'blog',
  `is_premium` tinyint(1) NOT NULL DEFAULT 0,
  `schema_type` varchar(100) DEFAULT 'Article',
  `article_section` varchar(255) DEFAULT NULL,
  `send_notification_email` tinyint(1) DEFAULT 0,
  `credits_required` int(11) NOT NULL DEFAULT 0,
  `homepage_featured_image` longtext DEFAULT NULL,
  `homepage_featured_order` int(11) DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `slug` (`slug`),
  KEY `idx_blogs_status` (`status`(20)),
  KEY `idx_blogs_date` (`date`),
  KEY `idx_blogs_homepage_featured` (`homepage_featured_order`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- --------------------------------------------------------
-- comments
-- parent_id added via add_parent_id_to_comments.sql
-- --------------------------------------------------------
CREATE TABLE IF NOT EXISTS `comments` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `post_id` varchar(255) NOT NULL,
  `user_name` longtext NOT NULL,
  `email` varchar(255) DEFAULT NULL,
  `content` longtext NOT NULL,
  `status` varchar(50) DEFAULT 'pending',
  `timestamp` datetime DEFAULT current_timestamp(),
  `edited_at` datetime DEFAULT NULL,
  `original_text` longtext DEFAULT NULL,
  `parent_id` int(11) DEFAULT NULL,
  `rejection_reason` longtext DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_comments_post_id` (`post_id`),
  KEY `idx_comments_status` (`status`(20))
) ENGINE=InnoDB AUTO_INCREMENT=2059 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- --------------------------------------------------------
-- contributors
-- --------------------------------------------------------
CREATE TABLE IF NOT EXISTS `contributors` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `full_name` longtext NOT NULL,
  `email` varchar(255) NOT NULL,
  `linkedin` longtext DEFAULT NULL,
  `country` longtext DEFAULT NULL,
  `organization` longtext DEFAULT NULL,
  `designation` longtext DEFAULT NULL,
  `role` varchar(50) DEFAULT NULL,
  `expertise` longtext DEFAULT NULL,
  `other_expertise` longtext DEFAULT NULL,
  `years_experience` longtext DEFAULT NULL,
  `short_bio` longtext DEFAULT NULL,
  `contribution_types` longtext DEFAULT NULL,
  `proposed_topics` longtext DEFAULT NULL,
  `contributed_elsewhere` longtext DEFAULT NULL,
  `previous_work_links` longtext DEFAULT NULL,
  `preferred_frequency` longtext DEFAULT NULL,
  `primary_motivation` longtext DEFAULT NULL,
  `weekly_time` longtext DEFAULT NULL,
  `volunteer_events` longtext DEFAULT NULL,
  `product_evaluation` longtext DEFAULT NULL,
  `personal_website` longtext DEFAULT NULL,
  `twitter_handle` longtext DEFAULT NULL,
  `status` varchar(50) DEFAULT 'pending',
  `created_at` datetime DEFAULT current_timestamp(),
  `image` varchar(255) DEFAULT NULL,
  `rejection_reason` longtext DEFAULT NULL,
  `is_deleted` tinyint(1) DEFAULT 0,
  `deleted_at` datetime DEFAULT NULL,
  `deletion_method` varchar(50) DEFAULT NULL,
  `deletion_ip` varchar(45) DEFAULT NULL,
  `deletion_confirmation_method` varchar(50) DEFAULT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=34 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- --------------------------------------------------------
-- contributor_applications
-- --------------------------------------------------------
CREATE TABLE IF NOT EXISTS `contributor_applications` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `full_name` longtext NOT NULL,
  `email` varchar(255) NOT NULL,
  `linkedin` longtext DEFAULT NULL,
  `country` longtext DEFAULT NULL,
  `organization` longtext DEFAULT NULL,
  `designation` longtext DEFAULT NULL,
  `role` varchar(50) DEFAULT NULL,
  `expertise` longtext DEFAULT NULL,
  `other_expertise` longtext DEFAULT NULL,
  `years_experience` longtext DEFAULT NULL,
  `short_bio` longtext DEFAULT NULL,
  `contribution_types` longtext DEFAULT NULL,
  `proposed_topics` longtext DEFAULT NULL,
  `contributed_elsewhere` longtext DEFAULT NULL,
  `previous_work_links` longtext DEFAULT NULL,
  `preferred_frequency` longtext DEFAULT NULL,
  `primary_motivation` longtext DEFAULT NULL,
  `weekly_time` longtext DEFAULT NULL,
  `volunteer_events` longtext DEFAULT NULL,
  `product_evaluation` longtext DEFAULT NULL,
  `personal_website` longtext DEFAULT NULL,
  `twitter_handle` longtext DEFAULT NULL,
  `status` varchar(50) DEFAULT 'pending',
  `created_at` datetime DEFAULT current_timestamp(),
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- --------------------------------------------------------
-- email_logs
-- --------------------------------------------------------
CREATE TABLE IF NOT EXISTS `email_logs` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `recipient` varchar(255) NOT NULL,
  `subject` varchar(255) NOT NULL,
  `status` varchar(20) DEFAULT 'pending',
  `error_message` longtext DEFAULT NULL,
  `created_at` datetime DEFAULT current_timestamp(),
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=16119 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- --------------------------------------------------------
-- email_queue
-- FIXED: charset changed from latin1 to utf8mb4 to support Unicode email content.
-- blog_id modified to VARCHAR(100) via fix_email_queue_blog_id.sql migration.
-- --------------------------------------------------------
CREATE TABLE IF NOT EXISTS `email_queue` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `recipient` varchar(255) NOT NULL,
  `subject` varchar(255) NOT NULL,
  `body` mediumtext NOT NULL,
  `status` varchar(50) NOT NULL DEFAULT 'pending',
  `attempts` int(11) NOT NULL DEFAULT 0,
  `error_message` text DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT current_timestamp(),
  `sent_at` timestamp NULL DEFAULT NULL,
  `blog_id` varchar(100) DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_email_queue_blog_recipient` (`blog_id`,`recipient`)
) ENGINE=InnoDB AUTO_INCREMENT=14977 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- --------------------------------------------------------
-- login_attempts
-- --------------------------------------------------------
CREATE TABLE IF NOT EXISTS `login_attempts` (
  `ip` varchar(45) NOT NULL,
  `attempts` int(11) DEFAULT 0,
  `last_attempt` int(11) DEFAULT NULL,
  PRIMARY KEY (`ip`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- --------------------------------------------------------
-- members
-- Includes columns added via db.js migrations:
--   receive_blog_emails, updated_at
-- --------------------------------------------------------
CREATE TABLE IF NOT EXISTS `members` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `name` longtext NOT NULL,
  `phone` longtext DEFAULT NULL,
  `email` varchar(255) NOT NULL,
  `location` longtext DEFAULT NULL,
  `password_hash` longtext NOT NULL,
  `status` varchar(50) NOT NULL DEFAULT 'pending',
  `created_at` datetime NOT NULL DEFAULT current_timestamp(),
  `approved_at` datetime DEFAULT NULL,
  `profile_image` longtext DEFAULT NULL,
  `rejection_reason` longtext DEFAULT NULL,
  `company_name` varchar(255) DEFAULT NULL,
  `job_role` varchar(255) DEFAULT NULL,
  `is_deleted` tinyint(1) DEFAULT 0,
  `deleted_at` datetime DEFAULT NULL,
  `deletion_method` varchar(50) DEFAULT NULL,
  `deletion_ip` varchar(45) DEFAULT NULL,
  `deletion_confirmation_method` varchar(50) DEFAULT NULL,
  `username` varchar(255) DEFAULT NULL,
  `receive_blog_emails` tinyint(1) NOT NULL DEFAULT 1,
  `updated_at` datetime DEFAULT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=411 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- --------------------------------------------------------
-- plagiarism_logs
-- --------------------------------------------------------
CREATE TABLE IF NOT EXISTS `plagiarism_logs` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `blog_id` int(11) DEFAULT NULL,
  `score` int(11) DEFAULT NULL,
  `raw_response` longtext DEFAULT NULL,
  `created_at` datetime DEFAULT current_timestamp(),
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=128 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- --------------------------------------------------------
-- post_views
-- Deduplication index added via add_post_views_dedup.sql
-- --------------------------------------------------------
CREATE TABLE IF NOT EXISTS `post_views` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `post_id` varchar(255) NOT NULL,
  `ip_address` varchar(45) DEFAULT NULL,
  `visitor_token` longtext DEFAULT NULL,
  `created_at` datetime DEFAULT current_timestamp(),
  PRIMARY KEY (`id`),
  KEY `idx_post_views_post_id` (`post_id`)
) ENGINE=InnoDB AUTO_INCREMENT=28 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- --------------------------------------------------------
-- users
-- full_name, email, profile_image, updated_at added via 20260227_add_profile_to_users.sql
-- All soft-delete columns present in production dump.
-- --------------------------------------------------------
CREATE TABLE IF NOT EXISTS `users` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `username` varchar(255) NOT NULL,
  `password` longtext NOT NULL,
  `role` varchar(50) NOT NULL DEFAULT 'contributor',
  `created_at` datetime DEFAULT current_timestamp(),
  `full_name` longtext DEFAULT NULL,
  `email` varchar(255) DEFAULT NULL,
  `avatar` longtext DEFAULT NULL,
  `updated_at` datetime DEFAULT NULL,
  `profile_image` varchar(255) DEFAULT NULL,
  `contributor_id` int(11) DEFAULT NULL,
  `is_active` int(11) NOT NULL DEFAULT 1,
  `bio` longtext DEFAULT NULL,
  `designation` longtext DEFAULT NULL,
  `linkedin` longtext DEFAULT NULL,
  `twitter_handle` longtext DEFAULT NULL,
  `personal_website` longtext DEFAULT NULL,
  `is_deleted` tinyint(1) DEFAULT 0,
  `deleted_at` datetime DEFAULT NULL,
  `deletion_method` varchar(50) DEFAULT NULL,
  `deletion_ip` varchar(45) DEFAULT NULL,
  `deletion_confirmation_method` varchar(50) DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `username` (`username`)
) ENGINE=InnoDB AUTO_INCREMENT=21 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- --------------------------------------------------------
-- user_permissions
-- can_access_premium_articles added via db.js migration
-- --------------------------------------------------------
CREATE TABLE IF NOT EXISTS `user_permissions` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `user_id` int(11) NOT NULL,
  `can_manage_blogs` int(11) NOT NULL DEFAULT 0,
  `can_manage_ads` int(11) NOT NULL DEFAULT 0,
  `can_manage_comments` int(11) NOT NULL DEFAULT 0,
  `can_manage_announcements` int(11) NOT NULL DEFAULT 0,
  `can_review_blogs` int(11) DEFAULT 0,
  `can_access_premium_articles` int(11) NOT NULL DEFAULT 0,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=29 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- --------------------------------------------------------
-- verification_codes
-- --------------------------------------------------------
CREATE TABLE IF NOT EXISTS `verification_codes` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `email` varchar(255) NOT NULL,
  `code` varchar(10) NOT NULL,
  `type` varchar(50) NOT NULL,
  `status` varchar(20) DEFAULT 'pending',
  `attempts` int(11) DEFAULT 0,
  `ip_address` varchar(45) DEFAULT NULL,
  `expires_at` datetime NOT NULL,
  `created_at` datetime DEFAULT current_timestamp(),
  PRIMARY KEY (`id`),
  KEY `idx_vc_email_type` (`email`, `type`)
) ENGINE=InnoDB AUTO_INCREMENT=411 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- =============================================================================
-- CREDIT SYSTEM TABLES (new — not in original dump)
-- =============================================================================

-- --------------------------------------------------------
-- credit_bundles  — purchasable credit packs
-- --------------------------------------------------------
CREATE TABLE IF NOT EXISTS `credit_bundles` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `name` varchar(255) NOT NULL,
  `credits` int(11) NOT NULL,
  `price_paise` int(11) NOT NULL,
  `is_active` tinyint(1) NOT NULL DEFAULT 1,
  `created_at` datetime DEFAULT current_timestamp(),
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- --------------------------------------------------------
-- member_credits  — current credit balance per member
-- --------------------------------------------------------
CREATE TABLE IF NOT EXISTS `member_credits` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `member_id` int(11) NOT NULL,
  `balance` int(11) NOT NULL DEFAULT 0,
  `updated_at` datetime DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_member_credits_member` (`member_id`),
  CONSTRAINT `fk_mc_member` FOREIGN KEY (`member_id`) REFERENCES `members` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- --------------------------------------------------------
-- credit_transactions  — full ledger of credit changes
-- --------------------------------------------------------
CREATE TABLE IF NOT EXISTS `credit_transactions` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `member_id` int(11) NOT NULL,
  `type` varchar(50) NOT NULL,
  `credits_delta` int(11) NOT NULL,
  `amount_paise` int(11) DEFAULT 0,
  `note` varchar(500) DEFAULT '',
  `razorpay_order_id` varchar(255) DEFAULT NULL,
  `created_at` datetime DEFAULT current_timestamp(),
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_ctx_order` (`razorpay_order_id`),
  KEY `idx_ctx_member` (`member_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- --------------------------------------------------------
-- payment_orders  — Razorpay order records (replay prevention)
-- --------------------------------------------------------
CREATE TABLE IF NOT EXISTS `payment_orders` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `razorpay_order_id` varchar(255) NOT NULL,
  `member_id` int(11) NOT NULL,
  `bundle_id` int(11) NOT NULL,
  `bundle_credits` int(11) NOT NULL,
  `bundle_price_paise` int(11) NOT NULL,
  `coupon_id` int(11) DEFAULT NULL,
  `final_price_paise` int(11) NOT NULL,
  `fulfilled` tinyint(1) NOT NULL DEFAULT 0,
  `created_at` datetime DEFAULT current_timestamp(),
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_po_order` (`razorpay_order_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- --------------------------------------------------------
-- member_blog_unlocks  — per-member article unlock records
-- --------------------------------------------------------
CREATE TABLE IF NOT EXISTS `member_blog_unlocks` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `member_id` int(11) NOT NULL,
  `blog_slug` varchar(255) NOT NULL,
  `credits_spent` int(11) NOT NULL DEFAULT 0,
  `unlocked_at` datetime DEFAULT current_timestamp(),
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_unlock` (`member_id`, `blog_slug`),
  KEY `idx_unlock_member` (`member_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- --------------------------------------------------------
-- coupons  — discount coupons for credit bundle purchases
-- --------------------------------------------------------
CREATE TABLE IF NOT EXISTS `coupons` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `code` varchar(100) NOT NULL,
  `discount_type` varchar(20) NOT NULL DEFAULT 'percentage',
  `discount_value` int(11) NOT NULL DEFAULT 0,
  `max_uses` int(11) NOT NULL DEFAULT 0,
  `used_count` int(11) NOT NULL DEFAULT 0,
  `is_active` tinyint(1) NOT NULL DEFAULT 1,
  `expires_at` datetime DEFAULT NULL,
  `created_at` datetime DEFAULT current_timestamp(),
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_coupon_code` (`code`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- --------------------------------------------------------
-- membership_plans  — legacy subscription plans (kept for FK compatibility)
-- --------------------------------------------------------
CREATE TABLE IF NOT EXISTS `membership_plans` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `name` varchar(255) NOT NULL,
  `price_paise` int(11) NOT NULL,
  `duration_days` int(11) NOT NULL DEFAULT 30,
  `description` text DEFAULT '',
  `is_active` tinyint(1) NOT NULL DEFAULT 1,
  `created_at` datetime DEFAULT current_timestamp(),
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- --------------------------------------------------------
-- member_subscriptions  — legacy subscription records (kept for FK compatibility)
-- --------------------------------------------------------
CREATE TABLE IF NOT EXISTS `member_subscriptions` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `member_id` int(11) NOT NULL,
  `plan_id` int(11) NOT NULL,
  `razorpay_order_id` varchar(255) DEFAULT NULL,
  `razorpay_payment_id` varchar(255) DEFAULT NULL,
  `status` varchar(50) NOT NULL DEFAULT 'active',
  `starts_at` datetime NOT NULL DEFAULT current_timestamp(),
  `expires_at` datetime NOT NULL,
  `created_at` datetime DEFAULT current_timestamp(),
  PRIMARY KEY (`id`),
  KEY `idx_sub_member` (`member_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- --------------------------------------------------------
-- password_reset_tokens
-- --------------------------------------------------------
CREATE TABLE IF NOT EXISTS `password_reset_tokens` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `email` varchar(255) NOT NULL,
  `token` varchar(500) NOT NULL,
  `expires_at` datetime NOT NULL,
  `created_at` datetime DEFAULT current_timestamp(),
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_prt_email` (`email`),
  KEY `idx_prt_email` (`email`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

