INSERT INTO `users` (`id`, `username`, `password`, `role`, `created_at`, `full_name`, `email`, `avatar`, `updated_at`, `profile_image`, `contributor_id`, `is_active`, `bio`, `designation`, `linkedin`, `twitter_handle`, `personal_website`, `is_deleted`, `deleted_at`, `deletion_method`, `deletion_ip`, `deletion_confirmation_method`) VALUES
(1, 'admin', '$2y$12$LgUH5m4jPCoIPbUrydcboeBdilpcOskNFjASwjea4MJf3vKngUfOa', 'admin', '2026-02-10 07:13:55', 'Raghu Boddu', 'admin@example.com', '/uploads/contributors/admin_69b27b261664e_1773304614.png', '2026-03-13 08:28:18', '/uploads/contributors/admin_69b27b261664e_1773304614.png', NULL, 1, 'Raghu Boddu is a technology leader and cybersecurity professional specializing in SAP Security, GRC, data protection, and enterprise risk management. He is the author of SAP Press books on SAP Access Control, SAP Process Control, and SAP Identity Access Governance (IAG). Raghu focuses on building practical, automation-driven solutions that help organizations achieve secure, compliant, and audit-ready operations across SAP and cloud landscapes. He regularly shares independent insights and hands-on experience for practitioners and leaders navigating evolving cybersecurity and regulatory challenges.', 'SAP Security Architect & ERP Cybersecurity Authority', 'https://www.linkedin.com/in/bodduraghu/', 'https://x.com/GRCwithRaghu', 'https://raghuboddu.com/', 0, NULL, NULL, NULL, NULL),
(2, 'inderdeep', '$2y$10$Z8BfT/RwV2gQ6eotcx/zQeNChbfuj36mN.gMCA5.mFQ7zOYFpa1W.', 'contributor', '2026-03-12 14:26:07', 'Inderdeep Singh', 'inderdeep@togglenow.com', '/uploads/contributors/admin_69b280e83c5bf_1773306088.png', '2026-06-22 14:43:49', '/uploads/contributors/admin_69b280e83c5bf_1773306088.png', 16, 1, 'A SAP Security professional with over 7+ years of experience specializing in SAP Authorizations, SAP GRC, and SAP S/4HANA Security, along with strong exposure to audit and compliance frameworks. I have successfully implemented access governance solutions, including SAP IAG, managed S/4HANA authorization upgrades, and conducted comprehensive SAP technical and functional audits to ensure control compliance.', 'Consultant - SAP Security & GRC', 'https://www.linkedin.com/in/inderdp', '', 'https://www.idsingh.com', 0, NULL, NULL, NULL, NULL),
(3, 'anjanaammu7995', '$2y$12$XhiJbRfswxAEe2.uhMhzb.Fmq62g4z81GZi7lwDHrFRjuTdFMinY6', 'contributor', '2026-03-12 20:21:27', NULL, 'anjanaammu7995@gmail.com', NULL, NULL, NULL, 15, 1, NULL, NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL),
